def match_parens(lst):
    # Check if the two strings contain only opening or closing parentheses
    if any(char not in ['(', ')'] for string in lst for char in string):
        return 'No'

    # Concatenate the two strings
    concatenated_string = lst[0] + lst[1]

    # Check if the resulting string is balanced
    stack = []
    for char in concatenated_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return 'No'
            stack.pop()

    if not stack:
        return 'Yes'
    else:
